  "settings.modelProvider.fieldHelp": "O {field}",
  "settings.modelProvider.help.contextWindow": "Pojemność kontekstu, którą model może przetworzyć naraz, w tokenach. ZAICODE używa tego do zarządzania kontekstem.\nNie przekraczaj rzeczywistego limitu modelu.",
  "settings.modelProvider.help.maxOutputTokens": "Maksymalna liczba tokenów, które jedno żądanie do modelu może wygenerować.\nNie przekraczaj rzeczywistego limitu modelu.",
  "settings.modelProvider.help.inputModalities": "Ustaw typy treści, które model może otrzymywać:\n\n- **Tekst**: Odbiera treść tekstową. Wymagane.\n- **Obrazy**: Odbiera treść graficzną.\n- **Wideo**: Odbiera treść wideo.\n- **PDF**: Odbiera dokumenty PDF bezpośrednio.",
  "settings.modelProvider.help.outputModalities": "Typ zawartości odpowiedzi modelu. Obecnie obsługiwany jest tylko tekst.",
  "settings.modelProvider.help.capabilities": "- **Wyjście strukturalne**: Obsługuje ograniczenia JSON Schema dla pól wyjściowych, typów i struktury.\n- **Wbudowane wyszukiwanie w sieci**: Obsługuje wbudowaną funkcję wyszukiwania w sieci w API modelu.\n- **Komunikaty systemowe w trakcie rozmowy**: Obsługuje wstawianie instrukcji systemowych podczas rozmowy.\n\nNie włączaj możliwości, których model nie obsługuje.",
  "settings.modelProvider.help.reasoningLevelsOrdered": "Ustaw poziomy rozumowania dostępne w czacie. **Musią być uporządkowane od najmniejszego do największego wysiłku rozumowania**.\nNie konfiguruj poziomów rozumowania, których model nie obsługuje.",
  "settings.modelProvider.help.reasoningLevelMapping": "Użyj wyrażenia CEL, aby zmapować bieżący poziom rozumowania, `reasoningLevel`, na pola żądania API modelu. Obiekt JSON zwrócony przez wyrażenie jest scalany z treścią wysyłanego żądania.",
  "settings.modelProvider.help.advanced": "**Schemat narzędzi MFJS**: Włącza zgodność z Moonshot Flavored JSON Schema, powszechnie używaną w API modeli Kimi firmy Moonshot. Włącz tylko wtedy, gdy API modelu wymaga tego formatu.",
  "settings.modelProvider.help.followRecommendedConfig": "Dopasowuje zalecaną konfigurację na podstawie ID modelu, Base URL i formatu API. ZAICODE stale aktualizuje zalecenia i automatycznie je synchronizuje.\nGdy zmienisz ustawienie ręcznie, przestaje ono podążać za aktualizacjami zaleceń; pozostałe ustawienia nadal są zarządzane przez inteligentną konfigurację.",
  "settings.modelProvider.modelDefaultsLoaded": "Inteligentna konfiguracja dopasowana do tego modelu",
