  "zaicode.help.what": "ZAICODE to Twój zespół agentów i pluton subagentów. Agenci wykonują pracę -> kolejka zadań ich wysyła -> wyniki trafiają do sesji.",
  "zaicode.help.step1": "1. Agenci i tryby (lewo): Hunter, Tester, Cleaner, Wikier, Translator i własne role. Kliknij tryb, aby go aktywować, potem przydziel zadania w kolejce, aby uwolnić agenta.",
  "zaicode.help.step2": "2. Kolejka (środek): Nowe zadanie -> opisz pracę -> wybierz agenta -> Dodaj. Przy włączonym Autopilot zadanie startuje samo.",
  "zaicode.help.step3": "3. Szczegóły (prawo): kliknij zadanie, aby zobaczyć status, błąd, wynik i otworzyć jego sesję czatu. Równolegle N ogranicza liczbę zadań działających naraz.",
  "zaicode.help.pools": "Pule: SAIRoute to Twój dostawca 9router. SAIFREN = darmowe modele internetowe, SAIOPP = płatne modele z głębokim rozumowaniem.",
